<?php
require __DIR__.'/../../core/init.php';if(session_status()!==PHP_SESSION_ACTIVE)session_start();header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');if(empty($_SESSION[USER_AUTH])){http_response_code(403);echo json_encode(['error'=>'Sign in to search.']);exit;}session_write_close();try{$q=is_string($_GET['q']??null)?$_GET['q']:'';echo json_encode(['results'=>array_slice(admin_search_results($q),0,6)],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT);}catch(Throwable $e){error_log('Search suggestions: '.$e->getMessage());http_response_code(500);echo json_encode(['error'=>'Suggestions are unavailable. Press Enter to search.']);}
